document.addEventListener('DOMContentLoaded', () => {
  const LANG = {
    PICK: 'Please select at least one category',
    PLURAL: 'Pick up to 2 categories',
    LIMIT: 'Category limit reached',
  }

  const select = document.getElementById('field21')
  if (!select) return

  select.multiple = true
  if (!/\[\]$/.test(select.name)) {
    select.name = `${select.name}[]`
  }

  select.style.display = 'none'

  // 3) Build our custom multi‐select UI
  const container = document.createElement('div')
  container.classList.add('multi-select')
  select.parentNode.insertBefore(container, select)

  const placeholder = document.createElement('div')
  placeholder.classList.add('multi-select-placeholder')
  placeholder.textContent = LANG.PLURAL
  container.appendChild(placeholder)

  const tagsContainer = document.createElement('div')
  tagsContainer.classList.add('tags')
  container.appendChild(tagsContainer)

  const dropdown = document.createElement('ul')
  dropdown.classList.add('multi-select-dropdown')
  container.appendChild(dropdown)

  const CATEGORY_LIMIT = 2
  const CATEGORY_LIMIT_MSG = LANG.LIMIT
  for (const opt of select.options) {
    const li = document.createElement('li')
    li.classList.add('multi-select-dropdown-item')
    li.setAttribute('data-value', opt.value)
    li.textContent = opt.text
    li.setAttribute('data-value', opt.value)
    li.addEventListener('click', e => {
      e.stopPropagation()
      if (tagsContainer.children.length < CATEGORY_LIMIT) {
        addTag(opt.value, opt.text)
      } else {
        // eslint-disable-next-line @github-ui/web-vitals/no-blocking-api-in-input-handler
        alert(CATEGORY_LIMIT_MSG)
      }
    })
    dropdown.appendChild(li)
  }

  placeholder.addEventListener('click', e => {
    e.stopPropagation()
    if (tagsContainer.children.length < 2) {
      dropdown.style.display = dropdown.style.display === 'block' ? 'none' : 'block'
    }
  })
  tagsContainer.addEventListener('click', e => {
    e.stopPropagation()
    if (tagsContainer.children.length < 2) {
      dropdown.style.display = dropdown.style.display === 'block' ? 'none' : 'block'
    }
  })
  document.addEventListener('click', () => {
    dropdown.style.display = 'none'
  })

  function addTag(value, label) {
    // avoid duplicates
    if ([...select.selectedOptions].some(o => o.value === value)) return

    // mark option selected
    const option = select.querySelector(`option[value="${value}"]`)
    if (option) option.selected = true

    select.dispatchEvent(new Event('change', {bubbles: true}))

    const tag = document.createElement('span')
    tag.classList.add('tag')
    tag.textContent = label

    const btn = document.createElement('button')
    btn.type = 'button'
    btn.classList.add('tag-remove')
    btn.textContent = '×'
    btn.addEventListener('click', e => {
      e.stopPropagation()
      removeTag(value, tag)
    })

    tag.appendChild(btn)
    tagsContainer.appendChild(tag)
    updatePlaceholder()
  }

  function removeTag(value, tagEl) {
    const option = select.querySelector(`option[value="${value}"]`)
    if (option) option.selected = false

    select.dispatchEvent(new Event('change', {bubbles: true}))

    tagsContainer.removeChild(tagEl)
    updatePlaceholder()
  }

  function updatePlaceholder() {
    if (tagsContainer.children.length >= 2) {
      placeholder.classList.add('hidden')
      dropdown.style.display = 'none'
    } else {
      placeholder.classList.remove('hidden')
    }
  }

  const form = select.closest('form')
  form.addEventListener('submit', e => {
    const techRadio = form.querySelector('input[name="partnershipType"][value="Technology Partner"]')
    if (techRadio && techRadio.checked) {
      const chosen = select.selectedOptions.length
      if (chosen === 0) {
        e.preventDefault()
      }
    }
  })
})
